    await writeFile(
      ledgerPath,
      JSON.stringify({ schemaVersion: 1, plugins: { [RETIRED]: { archiveDigest: "a".repeat(64), seededAt: "2026-01-01T00:00:00.000Z" }, [SUCCESSOR]: deployEntry } }),
      "utf8",
