    assert.equal((await resolveAgentPluginActivation(root, "evil-plugin")).verdict, "undetermined");
    assert.equal((await resolveAgentPluginActivation(root, "good-plugin")).verdict, "inactive");
  } finally {
    await forceRemove(root);
  }
});

