import { test, expect } from 'vitest';
import * as fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { createHash } from 'node:crypto';
import { createAgentPluginLayout } from '../../layout.js';
import { createInstallModule, type AgentPluginArchiveReaderPort } from '../../install.js';
import { createResolveAgentPluginRefsModule } from '../../resolve-agent-plugin-refs.js';
import { createPersistentStateModule } from '../../persistent-state.js';
import { createUninstallModule } from '../../uninstall.js';
import { ports as defaultPorts, assertContainedOnDisk, withFileLock } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';
import { migratePluginLayout } from '../../../../persistent-state.js';

test('neutral lifecycle uses Layout B, never refreezes a deduplicated install, and preserves notes/data through update', async () => {
  const temporary = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'jini-layout-b-')));
  const layout = createAgentPluginLayout({ root: temporary });
  const workspaceId = 'workspace-local';
  const workspace = layout.forWorkspace({ workspaceId });
  let freezeWrites = 0;
  const ports = { ...defaultPorts, layout, filesystem: { ...fs, chmod: (async (filename, mode) => {
    if (String(filename).includes('/package/sha256/')) freezeWrites++;
    return fs.chmod(filename, mode);
  }) as typeof fs.chmod } };
  const { installAgentPlugin } = createInstallModule(ports);
  const install = async (version: string) => {
    const archive = Buffer.from(version);
    const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
      for (const [entryPath, text] of [['plugin.json', JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'example', version })], ['skills/example/SKILL.md', '# Example\nGuidance']]) {
        yield { kind: 'file', entryPath: entryPath!, async *openReadStream() { yield Buffer.from(text!); } };
      }
    } };
    return installAgentPlugin({ layout, workspaceId, archive, archiveReader, expectedSha256: createHash('sha256').update(archive).digest('hex') });
  };
  try {
    const first = await install('1.0.0');
    expect(first.packageRoot).toBe(path.join(workspace.root, 'example', 'package', 'sha256', first.archiveDigest));
    const firstFreezeWrites = freezeWrites;
    expect(firstFreezeWrites).toBeGreaterThan(0);
    expect(await install('1.0.0')).toEqual(first);
    expect(freezeWrites).toBe(firstFreezeWrites);
    const memory = createPersistentStateModule(ports).memory({ workspaceRoot: workspace.root, pluginId: 'example' });
    await memory.writeNote({ entryPath: 'project.md', text: 'USER-CONTEXT' });
    await memory.learned.write({ entryPath: 'account.json', text: 'LEARNED-CACHE' });
    await fs.writeFile(path.join(workspace.pluginDataDir({ pluginId: 'example' }), 'cache'), 'STATE');
    const updated = await install('2.0.0');
    expect(await memory.read({ kind: 'notes', entryPath: 'project.md' })).toBe('USER-CONTEXT');
    expect(await memory.learned.read({ entryPath: 'account.json' })).toBe('LEARNED-CACHE');
    expect(await fs.readFile(path.join(workspace.pluginDataDir({ pluginId: 'example' }), 'cache'), 'utf8')).toBe('STATE');
    const refs = createResolveAgentPluginRefsModule(ports);
    expect(await refs.listInstalledPlugins(workspace.root)).toHaveLength(1);
    await expect(fs.stat(first.packageRoot)).rejects.toMatchObject({ code: 'ENOENT' });
    expect(JSON.parse(await fs.readFile(path.join(updated.packageRoot, 'plugin.json'), 'utf8')).version).toBe('2.0.0');
    const uninstall = createUninstallModule(ports);
    const request = { layout, workspaceId, pluginId: 'example' };
    await uninstall.uninstallAgentPlugin(request);
    expect(await refs.listInstalledPlugins(workspace.root)).toEqual([]);
    expect(await memory.read({ kind: 'notes', entryPath: 'project.md' })).toBe('USER-CONTEXT');
    await install('2.0.0');
    const resolved = await refs.resolveAgentPluginRefs(['example'], workspace, 'inject');
    expect(resolved.ok).toBe(true);
    if (resolved.ok) { expect(resolved.promptPrefix).toContain('USER-CONTEXT'); expect(resolved.promptPrefix).not.toContain('LEARNED-CACHE'); }
    const preview = await uninstall.previewAgentPluginUninstall(request);
    await uninstall.uninstallAgentPlugin(request, { confirmedPreview: preview, deleteMemory: true });
    await expect(fs.stat(workspace.pluginRootDir({ pluginId: 'example' }))).rejects.toMatchObject({ code: 'ENOENT' });
  } finally { await forceRemove(temporary); }
});

test('migration quarantines refused legacy entries without losing bytes and marks the layout complete once', async () => {
  const temporary = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'jini-quarantine-')));
  const events: { event: string; message: string }[] = [];
  const state = createPersistentStateModule({ ...defaultPorts, onEvent: event => events.push(event) });
  const malformed = `packages/sha256/${'a'.repeat(64)}`;
  const fileDigest = `packages/sha256/${'b'.repeat(64)}`;
  const refused = ['packages/sha256/not-a-digest', 'packages/sha256/..\\stray', fileDigest, `${malformed}/plugin.json`, 'memory/example', 'data/example', 'data/UPPER/cache'];
  try {
    for (const relative of refused) {
      await fs.mkdir(path.dirname(path.join(temporary, relative)), { recursive: true });
      await fs.writeFile(path.join(temporary, relative), `saved:${relative}`);
    }
    await fs.chmod(path.join(temporary, malformed), 0o555);
    expect(await state.migrate({ workspaceRoot: temporary })).toEqual({ complete: true, moved: 0 });
    expect(JSON.parse(await fs.readFile(path.join(temporary, '.agent-plugin-layout-migrated'), 'utf8'))).toEqual({ layoutVersion: 2 });
    const quarantine = path.join(temporary, 'staging', 'legacy-quarantine');
    const runs = await fs.readdir(quarantine);
    expect(runs).toHaveLength(1);
    for (const relative of refused) {
      expect(await fs.readFile(path.join(quarantine, runs[0]!, relative), 'utf8')).toBe(`saved:${relative}`);
      await expect(fs.stat(path.join(temporary, relative))).rejects.toMatchObject({ code: 'ENOENT' });
    }
    expect((await fs.stat(path.join(quarantine, runs[0]!, malformed))).mode & 0o777).toBe(0o555);
    const quarantined = events.filter(event => event.event === 'migration-quarantined');
    expect(quarantined).toHaveLength(7);
    expect(quarantined.every(event => event.message.includes(quarantine))).toBe(true);
    expect(events.some(event => event.event === 'migration-failed')).toBe(false);
    events.length = 0;
    expect(await state.migrate({ workspaceRoot: temporary })).toEqual({ complete: true, moved: 0 });
    expect(events).toEqual([]);
    expect(await fs.readdir(quarantine)).toEqual(runs);
  } finally { await forceRemove(temporary); }
});

test('Layout B wins package and mutable-state conflicts while every legacy copy survives in quarantine', async () => {
  const temporary = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'jini-quarantine-conflict-')));
  const digest = 'c'.repeat(64);
  const pairs = [
    [`packages/sha256/${digest}`, `example/package/sha256/${digest}`],
    ['memory/example', 'example/memory'], ['data/example', 'example/data'],
  ];
  try {
    for (const [legacy, current] of pairs) {
      for (const [relative, copy] of [[legacy!, 'legacy'], [current!, 'current']]) {
        await fs.mkdir(path.join(temporary, relative!), { recursive: true });
        await fs.writeFile(path.join(temporary, relative!, 'saved'), copy!);
      }
    }
    await fs.writeFile(path.join(temporary, pairs[0]![0]!, 'plugin.json'), JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'example' }));
    const events: string[] = [];
    const state = createPersistentStateModule({ ...defaultPorts, onEvent: ({ event }) => events.push(event) });
    expect(await state.migrate({ workspaceRoot: temporary })).toEqual({ complete: true, moved: 0 });
    const quarantine = path.join(temporary, 'staging', 'legacy-quarantine');
    const [run] = await fs.readdir(quarantine);
    for (const [legacy, current] of pairs) {
      expect(await fs.readFile(path.join(temporary, current!, 'saved'), 'utf8')).toBe('current');
      expect(await fs.readFile(path.join(quarantine, run!, legacy!, 'saved'), 'utf8')).toBe('legacy');
      await expect(fs.stat(path.join(temporary, legacy!))).rejects.toMatchObject({ code: 'ENOENT' });
    }
    expect(events.filter(event => event === 'migration-quarantined')).toHaveLength(3);
    expect(await state.migrate({ workspaceRoot: temporary })).toEqual({ complete: true, moved: 0 });
  } finally { await forceRemove(temporary); }
});

test.each(['move', 'quarantine'])('a genuine migration %s failure preserves the source and refuses the completion marker', async kind => {
  const temporary = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'jini-move-failure-')));
  const legacy = path.join(temporary, 'packages', 'sha256', 'd'.repeat(64));
  try {
    await fs.mkdir(legacy, { recursive: true });
    await fs.writeFile(path.join(legacy, 'plugin.json'), kind === 'quarantine' ? 'bad json' : JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'example' }));
    const events: string[] = [];
    const state = createPersistentStateModule({ ...defaultPorts, filesystem: { ...fs,
      rename: (async (from, to) => {
        if (String(from) === legacy) throw new Error('move still in flight');
        return fs.rename(from, to);
      }) as typeof fs.rename,
    }, onEvent: ({ event }) => events.push(event) });
    expect((await state.migrate({ workspaceRoot: temporary })).complete).toBe(false);
    expect((await fs.stat(legacy)).isDirectory()).toBe(true);
    await expect(fs.stat(path.join(temporary, '.agent-plugin-layout-migrated'))).rejects.toMatchObject({ code: 'ENOENT' });
    expect(events).toContain('migration-failed');
    expect(events).not.toContain('migration-quarantined');
  } finally { await forceRemove(temporary); }
});

test.each(['migration', 'plugin'])('a held %s lock prevents migration completion without quarantining a valid source', async held => {
  const temporary = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'jini-migration-lock-')));
  const legacy = path.join(temporary, 'packages', 'sha256', 'e'.repeat(64));
  try {
    await fs.mkdir(legacy, { recursive: true });
    await fs.writeFile(path.join(legacy, 'plugin.json'), '{"name":"example"}');
    const request = { filesystem: fs, workspaceRoot: temporary,
      contain: ({ root, entryPath }: { root: string; entryPath: string }) => assertContainedOnDisk(root, entryPath),
      parsePluginId: ({ value }: { value: unknown }) => (value as { name: string }).name,
      // Simulate the lock port's refusal, keeping the real migration and filesystem operations.
      withLock: <T>({ lockPath, run }: { lockPath: string; run(): Promise<T> }): Promise<T> => {
        if (held === 'migration' || lockPath.includes('.plugin-state-')) return Promise.reject(new Error('lock held'));
        return withFileLock({ lockPath, run }, { staleMs: Infinity, createParent: true });
      },
    };
    if (held === 'migration') await expect(migratePluginLayout(request)).rejects.toThrow('lock held');
    else expect((await migratePluginLayout(request)).complete).toBe(false);
    expect((await fs.stat(legacy)).isDirectory()).toBe(true);
    await expect(fs.stat(path.join(temporary, '.agent-plugin-layout-migrated'))).rejects.toMatchObject({ code: 'ENOENT' });
    await expect(fs.stat(path.join(temporary, 'staging', 'legacy-quarantine'))).rejects.toMatchObject({ code: 'ENOENT' });
  } finally { await forceRemove(temporary); }
});

src/__tests__/folder-zip-node.characteri.source:
import assert from "node:assert/strict";
import { constants } from "node:fs";
import path from "node:path";
import { beforeEach, test, vi } from "vitest";
import { FOLDER_MAX_FILES, FolderZipError, zipFolderFiles } from "../folder-zip.js";
import { zipLocalFolder } from "../folder-zip-node.js";

type Entry = { name: string; isDirectory(): boolean; isFile(): boolean };
type Handle = {
  stat(): Promise<{ size: number; isFile(): boolean }>;
  read(buffer: Buffer, offset: number, length: number, position: null): Promise<{ bytesRead: number }>;
  close(): Promise<void>;
};
const filesystem = vi.hoisted(() => ({
  realpath: vi.fn<(filename: string) => Promise<string>>(),
  lstat: vi.fn<(filename: string) => Promise<{ isDirectory(): boolean }>>(),
  opendir: vi.fn<(filename: string) => Promise<AsyncIterable<Entry>>>(),
  open: vi.fn<(filename: string, flags: number) => Promise<Handle>>(),
}));
vi.mock("node:fs/promises", () => filesystem);

const root = path.resolve("/picked");
let entries: Entry[];
let content: Buffer;
let info: { size: number; isFile(): boolean };
let cursor: number;
const handle = {
  stat: vi.fn<Handle["stat"]>(),
  read: vi.fn<Handle["read"]>(),
  close: vi.fn<Handle["close"]>(),
} satisfies Handle;

function entry(required: { name: string; kind?: "file" | "directory" | "special" }, _optional: Record<string, never> = {}): Entry {
  const kind = required.kind ?? "file";
  return { name: required.name, isDirectory: () => kind === "directory", isFile: () => kind === "file" };
}

async function* listing(required: { entries: Entry[] }, _optional: Record<string, never> = {}): AsyncIterable<Entry> {
  yield* required.entries;
}

beforeEach(() => {
  vi.resetAllMocks();
  entries = [entry({ name: "a" })];
  content = Buffer.from([1, 2]);
  info = { size: 2, isFile: () => true };
  cursor = 0;
  filesystem.realpath.mockImplementation(async filename => filename);
  filesystem.lstat.mockResolvedValue({ isDirectory: () => true });
  filesystem.opendir.mockImplementation(async () => listing({ entries }));
  filesystem.open.mockImplementation(async () => { cursor = 0; return handle; });
  handle.stat.mockImplementation(async () => info);
  handle.read.mockImplementation(async (buffer, offset, length) => {
    const count = content.copy(buffer, offset, cursor, cursor + Math.min(length, 1));
    cursor += count;
    return { bytesRead: count };
  });
  handle.close.mockResolvedValue(undefined);
});

const unreadable = { reason: "unreadable", message: "Could not read that folder. Try again." };

test("local reads retain partial chunks, stop at EOF and close the descriptor", async () => {
  const file = new File([new Uint8Array(content)], "a");
  Object.defineProperty(file, "webkitRelativePath", { value: "picked/a" });
  const expected = await zipFolderFiles({ files: [file], maxBytes: 1024 });
  assert.deepEqual(await zipLocalFolder({ path: root, maxBytes: 1024 }), new Uint8Array(await expected.arrayBuffer()));
  assert.equal(handle.read.mock.calls.length, 3);
  assert.deepEqual(handle.read.mock.calls.map(call => [call[1], call[2], call[3]]), [[0, 3, null], [1, 2, null], [2, 1, null]]);
  assert.equal(handle.close.mock.calls.length, 1);
  assert.deepEqual(filesystem.open.mock.calls, [[path.join(root, "a"), constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK]]);
});

test("an empty file is accepted after its EOF is confirmed", async () => {
  content = Buffer.alloc(0);
  info.size = 0;
  const bytes = await zipLocalFolder({ path: root, maxBytes: 100 });
  assert.equal(bytes.length, 100);
  assert.equal(handle.read.mock.calls.length, 1);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("nested directories are traversed and entries are sorted independently of enumeration order", async () => {
  filesystem.opendir.mockImplementation(async filename => listing({ entries: filename === root
    ? [entry({ name: "z" }), entry({ name: "dir", kind: "directory" }), entry({ name: "a" })]
    : [entry({ name: "b" })] }));
  const files = ["a", "dir/b", "z"].map(name => {
    const file = new File([new Uint8Array(content)], path.basename(name));
    Object.defineProperty(file, "webkitRelativePath", { value: `picked/${name}` });
    return file;
  });
  const expected = await zipFolderFiles({ files, maxBytes: 1024 });
  assert.deepEqual(await zipLocalFolder({ path: root, maxBytes: 1024 }), new Uint8Array(await expected.arrayBuffer()));
  assert.deepEqual(filesystem.opendir.mock.calls, [[root], [path.join(root, "dir")]]);
  assert.equal(handle.close.mock.calls.length, 3);
});

test("equal relative paths keep duplicate files in the archive", async () => {
  entries.push(entry({ name: "a" }));
  const bytes = await zipLocalFolder({ path: root, maxBytes: 1024 });
  assert.equal(new DataView(bytes.buffer).getUint16(bytes.length - 14, true), 2);
  assert.equal(handle.close.mock.calls.length, 2);
});

test("non-directories are refused before opening a directory", async () => {
  filesystem.lstat.mockResolvedValue({ isDirectory: () => false });
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.opendir.mock.calls.length, 0);
  assert.equal(filesystem.realpath.mock.calls.length, 1);
});

test("a directory whose real path changes is refused before enumeration", async () => {
  filesystem.realpath.mockResolvedValueOnce(root).mockResolvedValueOnce(path.resolve("/elsewhere"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.opendir.mock.calls.length, 0);
});

test("special entries are refused before opening a file", async () => {
  entries = [entry({ name: "link", kind: "special" })];
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.open.mock.calls.length, 0);
});

test("files whose real paths differ are refused before opening", async () => {
  filesystem.realpath.mockImplementation(async filename => filename === root ? root : path.resolve("/outside"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(filesystem.open.mock.calls.length, 0);
});

test("an opened special file is refused and its descriptor is closed", async () => {
  info.isFile = () => false;
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.read.mock.calls.length, 0);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("cumulative raw sizes are bounded before the next allocation or read", async () => {
  entries.push(entry({ name: "b" }));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 3 }), {
    reason: "too-large", message: "Folder is over the upload limit.",
  });
  assert.equal(handle.read.mock.calls.length, 3);
  assert.equal(handle.close.mock.calls.length, 2);
});

test("growth beyond the stat size is detected with one extra byte and closes the file", async () => {
  info.size = 1;
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.read.mock.calls.length, 2);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("shrinkage below the stat size is refused and closes the file", async () => {
  info.size = 3;
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("read and stat failures are translated after closing the file", async () => {
  handle.read.mockRejectedValueOnce(new Error("read failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 1);
  handle.stat.mockRejectedValueOnce(new Error("stat failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 2);
});

test("close failures override a raw-size refusal and become unreadable", async () => {
  handle.close.mockRejectedValueOnce(new Error("close failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1 }), unreadable);
  assert.equal(handle.read.mock.calls.length, 0);
  assert.equal(handle.close.mock.calls.length, 1);
});

test("native root, enumeration and open failures become unreadable refusals", async () => {
  filesystem.realpath.mockRejectedValueOnce(new Error("realpath failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  filesystem.opendir.mockRejectedValueOnce(new Error("opendir failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  filesystem.open.mockRejectedValueOnce(new Error("open failed"));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), unreadable);
  assert.equal(handle.close.mock.calls.length, 0);
});

test("existing FolderZipError instances are rethrown unchanged", async () => {
  const error = new FolderZipError("too-many", "original message");
  filesystem.realpath.mockRejectedValueOnce(error);
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), caught => caught === error);
});

test("the entry cap counts directories and refuses the next entry before opening it", async () => {
  entries = Array.from({ length: FOLDER_MAX_FILES + 1 }, (_, i) => entry({ name: String(i), kind: "directory" }));
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), {
    reason: "too-many", message: "More than 4096 entries.",
  });
  assert.equal(filesystem.opendir.mock.calls.length, 1);
  assert.equal(filesystem.open.mock.calls.length, 0);
});

test("an empty traversal preserves the encoder's empty-folder refusal", async () => {
  entries = [];
  await assert.rejects(() => zipLocalFolder({ path: root, maxBytes: 1024 }), {
    reason: "empty", message: "That folder is empty.",
  });
});

test("a parent swapped for a symlink after realpath can supply outside bytes (reported, not fixed)", async () => {
  const actual = await vi.importActual<typeof import("node:fs/promises")>("node:fs/promises");
  const { tmpdir } = await import("node:os");
  const temporary = await actual.realpath(await actual.mkdtemp(path.join(tmpdir(), "folder-zip-parent-race-")));
  try {
    const selected = path.join(temporary, "selected");
    const outside = path.join(temporary, "outside");
    await actual.mkdir(selected);
    await actual.mkdir(outside);
    await actual.writeFile(path.join(selected, "a"), "selected bytes");
    await actual.writeFile(path.join(outside, "a"), "outside bytes");
    filesystem.realpath.mockImplementation(filename => actual.realpath(filename));
    filesystem.lstat.mockImplementation(filename => actual.lstat(filename));
    filesystem.opendir.mockImplementation(filename => actual.opendir(filename));
    filesystem.open.mockImplementation(async (filename, flags) => {
      await actual.rename(selected, path.join(temporary, "original"));
      await actual.symlink(outside, selected);
      return actual.open(filename, flags);
    });
    const file = new File(["outside bytes"], "a");
    Object.defineProperty(file, "webkitRelativePath", { value: "picked/a" });
    const expected = await zipFolderFiles({ files: [file], maxBytes: 1024 });
    assert.deepEqual(await zipLocalFolder({ path: selected, maxBytes: 1024 }), new Uint8Array(await expected.arrayBuffer()));
  } finally { await actual.rm(temporary, { recursive: true, force: true }); }
});

