import { expect, test } from 'vitest';
import * as fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import {
  AgentPluginHostIncompatibleError, AgentPluginNotInstalledError, INVALID_AGENT_PLUGIN_HOST_RANGE,
  createAgentPluginLayout, createAgentPluginLifecycle, type AgentPluginArchiveReaderPort,
} from '../../index.js';
import { createPersistentStateModule } from '../../persistent-state.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

/** Real temp filesystem; archive bytes come from an injected reader port instead of a zip. */
const workspaceId = 'workspace-a';
const namespace = ports.extensionNamespace;
type Layout = ReturnType<typeof createAgentPluginLayout>;

function archiveInput(layout: Layout, pluginId: string, extension: Record<string, unknown>) {
  const files = {
    'plugin.json': JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: pluginId, version: '1.0.0',
      extensions: { [namespace]: extension } }),
    [`skills/${pluginId}/SKILL.md`]: `# ${pluginId}\nGuidance.`,
  };
  const archive = Buffer.from(JSON.stringify(files));
  const archiveReader: AgentPluginArchiveReaderPort = { async *entries() {
    for (const [entryPath, text] of Object.entries(files)) yield { kind: 'file', entryPath, openReadStream: async function* () { yield Buffer.from(text); } };
  } };
  return { archive, archiveReader, expectedSha256: createHash('sha256').update(archive).digest('hex'), layout, workspaceId };
}

async function withHarness(run: (h: { api: ReturnType<typeof createAgentPluginLifecycle>; layout: Layout; workspaceRoot: string;
  context: typeof ports; install: (pluginId: string, extension?: Record<string, unknown>) => Promise<void> }) => Promise<void>) {
  const temp = await fs.mkdtemp(path.join(os.tmpdir(), 'plugin-set-enabled-'));
  try {
    const layout = createAgentPluginLayout({ root: path.join(temp, 'plugins') });
    const context = { ...ports, layout };
    const api = createAgentPluginLifecycle(context);
    const workspaceRoot = layout.forWorkspace({ workspaceId }).root;
    const install = async (pluginId: string, extension: Record<string, unknown> = {}) => { await api.installAgentPlugin(archiveInput(layout, pluginId, extension)); };
    await run({ api, layout, workspaceRoot, context, install });
  } finally { await forceRemove(temp); }
}

const toggle = (pluginId: string, enabled: boolean) => ({ workspaceId, pluginId, enabled, actor: 'operator:alice' });

test('installed index carries requires/hostRange from the host namespace, and omits them when absent', async () => {
  await withHarness(async ({ api, workspaceRoot, install }) => {
    await install('needs-cap', { requires: ['cap:x', 'cap:x'], hostRange: '^1' });
    await install('plain');
    const listed = await api.listInstalledPlugins({ workspaceRoot });
    const byId = Object.fromEntries(listed.map(plugin => [plugin.pluginId, plugin]));
    expect([byId['needs-cap']!.requires, byId['needs-cap']!.hostRange]).toEqual([['cap:x'], '^1']);
    expect('requires' in byId['plain']! || 'hostRange' in byId['plain']!).toBe(false);
  });
});

test('enabling a host-incompatible or malformed-range plugin is refused before any activation write', async () => {
  await withHarness(async ({ api, workspaceRoot, install }) => {
    await install('future', { hostRange: '>=99' });
    await install('garbled', { hostRange: 42 });
    for (const pluginId of ['future', 'garbled']) {
      const refusal = api.setAgentPluginEnabled(toggle(pluginId, true));
      await expect(refusal).rejects.toBeInstanceOf(AgentPluginHostIncompatibleError);
      await expect(refusal).rejects.toMatchObject({ code: 'PLUGIN_HOST_INCOMPATIBLE' });
    }
    expect((await api.listInstalledPlugins({ workspaceRoot })).find(p => p.pluginId === 'garbled')!.hostRange).toBe(INVALID_AGENT_PLUGIN_HOST_RANGE);
    const activations = await api.readAgentPluginActivations({ workspaceRoot });
    expect(Object.hasOwn(activations.plugins, 'future') || Object.hasOwn(activations.plugins, 'garbled')).toBe(false);
    // Disabling is never refused: an operator must always be able to turn an incompatible plugin off.
    expect(await api.setAgentPluginEnabled(toggle('future', false))).toEqual({ pluginId: 'future', enabled: false });
  });
});

test('enabling with unmet requirements succeeds and warns; disabled providers do not satisfy them', async () => {
  await withHarness(async ({ api, install }) => {
    await install('consumer', { requires: ['cap:a', 'cap:b'], hostRange: '^1' });
    await install('provider-a', { provides: ['cap:a'] });
    await install('provider-b', { provides: ['cap:b'] });
    await api.setAgentPluginEnabled(toggle('provider-b', false));
    expect(await api.setAgentPluginEnabled(toggle('consumer', true))).toEqual({ pluginId: 'consumer', enabled: true, warnings: ['Needs cap:b'] });
    expect(await api.setAgentPluginEnabled(toggle('provider-b', true))).toEqual({ pluginId: 'provider-b', enabled: true });
    expect(await api.setAgentPluginEnabled(toggle('consumer', true))).toEqual({ pluginId: 'consumer', enabled: true });
  });
});

test('disabling a provider an active plugin needs succeeds and names the dependent', async () => {
  await withHarness(async ({ api, install }) => {
    await install('consumer', { requires: ['cap:a'] });
    await install('provider-a', { provides: ['cap:a'] });
    expect(await api.setAgentPluginEnabled(toggle('provider-a', false)))
      .toEqual({ pluginId: 'provider-a', enabled: false, warnings: ['consumer needs cap:a'] });
    await api.setAgentPluginEnabled(toggle('consumer', false));
    await api.setAgentPluginEnabled(toggle('provider-a', true));
    expect(await api.setAgentPluginEnabled(toggle('provider-a', false))).toEqual({ pluginId: 'provider-a', enabled: false });
  });
});

test('an unknown or ungrammatical id is a not-installed refusal that creates no workspace or lock files', async () => {
  await withHarness(async ({ api, workspaceRoot }) => {
    for (const pluginId of ['missing', 'Not_A_Valid_Id', 'staging']) {
      await expect(api.setAgentPluginEnabled(toggle(pluginId, true))).rejects.toBeInstanceOf(AgentPluginNotInstalledError);
    }
    await expect(fs.stat(workspaceRoot)).rejects.toMatchObject({ code: 'ENOENT' });
  });
});

test('a toggle waits for the per-plugin state lock and re-checks installation once it holds it', async () => {
  await withHarness(async ({ api, workspaceRoot, context, install }) => {
    await install('held');
    let release!: () => void;
    const released = new Promise<void>(resolve => { release = resolve; });
    let entered!: () => void;
    const holding = new Promise<void>(resolve => { entered = resolve; });
    const holder = createPersistentStateModule(context).withPluginLock({ workspaceRoot, pluginId: 'held', run: async () => {
      entered();
      await released;
      // Simulates an uninstall finishing while the toggle waited for the lock.
      const [plugin] = await api.listInstalledPlugins({ workspaceRoot });
      await forceRemove(plugin!.packageRoot);
    } });
    await holding;
    let settled = false;
    const toggled = api.setAgentPluginEnabled(toggle('held', true)).finally(() => { settled = true; });
    await new Promise(resolve => setTimeout(resolve, 150));
    expect(settled).toBe(false);
    release();
    await holder;
    await expect(toggled).rejects.toBeInstanceOf(AgentPluginNotInstalledError);
    const activations = await api.readAgentPluginActivations({ workspaceRoot });
    expect(Object.hasOwn(activations.plugins, 'held')).toBe(false);
  });
});

test('with two installed digests of one id, enable is refused when ANY revision is host-incompatible', async () => {
  await withHarness(async ({ api, layout, workspaceRoot, install }) => {
    await install('twin', { hostRange: '^1' });
    const packagesDir = layout.forWorkspace({ workspaceId }).pluginPackagesDir({ pluginId: 'twin' });
    const [digest] = await fs.readdir(packagesDir);
    const stale = path.join(packagesDir, 'f'.repeat(64));
    await fs.cp(path.join(packagesDir, digest!), stale, { recursive: true });
    await fs.chmod(stale, 0o700);
    await fs.chmod(path.join(stale, 'plugin.json'), 0o600);
    const raw = JSON.parse(await fs.readFile(path.join(stale, 'plugin.json'), 'utf8'));
    raw.extensions[namespace].hostRange = '>=99';
    await fs.writeFile(path.join(stale, 'plugin.json'), JSON.stringify(raw));
    expect((await api.listInstalledPlugins({ workspaceRoot })).filter(plugin => plugin.pluginId === 'twin')).toHaveLength(2);
    await expect(api.setAgentPluginEnabled(toggle('twin', true))).rejects.toBeInstanceOf(AgentPluginHostIncompatibleError);
  });
});

src/lifecycle/__tests__/unit/install-edg.source:
import { afterEach, describe, expect, test } from 'vitest';
import { createHash } from 'node:crypto';
import * as fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createAgentPluginLayout } from '../../layout.js';
import { AgentPluginInstallError, createInstallModule, type AgentPluginArchiveEntry, type AgentPluginArchiveReaderPort } from '../../install.js';
import type { AgentPluginLifecyclePorts, FilesystemPort } from '../../ports.js';
import { PackagePathViolation } from '../../package-paths.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

/**
 * @file `installAgentPlugin` refusal paths that need an adversarial archive reader or an injected
 * filesystem fault: the archive cap, a reader that changes its entries between passes, extraction
 * containment faults, publication over a non-directory, and the host's identity-admission port.
 */

const temporaries: string[] = [];
afterEach(async () => { for (const dir of temporaries.splice(0)) await forceRemove(dir); });
async function tempRoot(): Promise<string> {
  const dir = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'install-edges-')));
  temporaries.push(dir);
  return dir;
}
const manifest = JSON.stringify({ $schema: 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json', name: 'edge-plugin', version: '1.0.0' });
function fileEntry(entryPath: string, text: string): AgentPluginArchiveEntry {
  return { kind: 'file', entryPath, async *openReadStream() { yield Buffer.from(text); } };
}
function readerOf(...passes: AgentPluginArchiveEntry[][]): AgentPluginArchiveReaderPort {
  let pass = 0;
  return { async *entries() { yield* passes[Math.min(pass++, passes.length - 1)]!; } };
}
const basicEntries = () => [fileEntry('plugin.json', manifest), fileEntry('skills/edge-plugin/SKILL.md', '# Edge\n')];
async function install(overrides: Partial<AgentPluginLifecyclePorts>, archiveReader: AgentPluginArchiveReaderPort, archive = Buffer.from('edge-archive')) {
  const root = await tempRoot();
  const layout = createAgentPluginLayout({ root });
  const { installAgentPlugin } = createInstallModule({ ...ports, layout, ...overrides });
  const expectedSha256 = createHash('sha256').update(archive).digest('hex');
  return { root, result: installAgentPlugin({ layout, workspaceId: 'ws', archive, archiveReader, expectedSha256 }) };
}
async function installError(promise: Promise<unknown>): Promise<AgentPluginInstallError> {
  const error = await promise.then(() => undefined, (caught: unknown) => caught);
  expect(error).toBeInstanceOf(AgentPluginInstallError);
  return error as AgentPluginInstallError;
}

describe('installAgentPlugin refusals', () => {
  test('an archive over the byte cap is refused before hashing or extraction', async () => {
    const { maxAgentPluginInstallArchiveBytes } = createInstallModule(ports);
    const archive = Buffer.alloc(maxAgentPluginInstallArchiveBytes() + 1);
    const { root, result } = await install({}, readerOf(basicEntries()), archive);
    const error = await installError(result);
    expect(error.code).toBe('ARCHIVE_TOO_LARGE');
    expect(error.message).toBe(`archive is ${archive.byteLength} bytes, over the ${maxAgentPluginInstallArchiveBytes()}-byte cap`);
    await expect(fs.stat(path.join(root, 'ws'))).rejects.toMatchObject({ code: 'ENOENT' });
  });

  test('a reader that yields more entries on the extraction pass than the counted pass is still capped', async () => {
    const many = Array.from({ length: 4097 }, (_, index) => fileEntry(`f${index}.md`, 'x'));
    const { result } = await install({}, readerOf(basicEntries(), [...basicEntries(), ...many]));
    expect((await installError(result)).code).toBe('TOO_MANY_ENTRIES');
  }, 30_000);

  test('a containment fault while extracting is re-shaped as an unsafe entry, keeping only a path-violation cause', async () => {
    // The extraction root itself cannot be resolved: a device fault, not a path violation.
    const deviceFault = { ...fs, realpath: (async (target: string) => {
      if (target.endsWith(`${path.sep}root`)) throw Object.assign(new Error('EIO: device fault'), { code: 'EIO' });
      return fs.realpath(target);
    }) as FilesystemPort['realpath'] } as FilesystemPort;
    const io = await installError((await install({ filesystem: deviceFault }, readerOf(basicEntries()))).result);
    expect(io).toMatchObject({ code: 'UNSAFE_ENTRY_PATH', message: "archive entry resolves outside the package root: 'plugin.json'" });
    expect(io.cause).toBeUndefined();
    // A directory that resolves elsewhere, as a planted symlink would: a real path violation.
    const redirected = { ...fs, realpath: (async (target: string) => (target.endsWith(`${path.sep}escapes`) ? '/' : fs.realpath(target))) as FilesystemPort['realpath'] } as FilesystemPort;
    const escape = await installError((await install({ filesystem: redirected }, readerOf([fileEntry('plugin.json', manifest), fileEntry('escapes/x.md', 'x')]))).result);
    expect(escape.code).toBe('UNSAFE_ENTRY_PATH');
    expect(escape.cause).toBeInstanceOf(PackagePathViolation);
  });
});

describe('publication', () => {
  test('a rename that reports an existing destination which is not a real directory fails publication', async () => {
    let finalRoot = '';
    const racing = { ...fs, rename: (async (from: string, to: string) => {
      if (path.basename(from) === 'root') { finalRoot = to; throw Object.assign(new Error('EEXIST: exists'), { code: 'EEXIST' }); }
      return fs.rename(from, to);
    }) as FilesystemPort['rename'] } as FilesystemPort;
    const error = await installError((await install({ filesystem: racing }, readerOf(basicEntries()))).result);
    expect(error).toMatchObject({ code: 'PUBLISH_FAILED', message: `'${finalRoot}' exists but is not a real, published package directory` });
  });

  test('a stat fault other than ENOENT on the destination propagates unchanged', async () => {
    const faulting = { ...fs, stat: (async (target: string, ...rest: []) => {
      if (/[a-f0-9]{64}$/.test(target)) throw Object.assign(new Error('EIO: stat fault'), { code: 'EIO' });
      return fs.stat(target, ...rest);
    }) as FilesystemPort['stat'] } as FilesystemPort;
    await expect((await install({ filesystem: faulting }, readerOf(basicEntries()))).result).rejects.toMatchObject({ code: 'EIO' });
  });

  test('a host identity-admission port wraps publication with the manifest identity', async () => {
    const admitted: Array<{ id: string; localId: string }> = [];
    const identityAdmission = async <T>({ id, localId, run }: { id: string; localId: string; run: () => Promise<T> }) => {
      admitted.push({ id, localId });
      return run();
    };
    const { result } = await install({ identityAdmission }, readerOf(basicEntries()));
    const installed = await result;
    expect(installed.pluginId).toBe('edge-plugin');
    expect(admitted).toEqual([{ id: installed.id, localId: 'edge-plugin' }]);
    expect((await fs.stat(installed.packageRoot)).isDirectory()).toBe(true);
  });

  test('a fault scanning for superseded revisions warns without failing the accepted install', async () => {
    const events: Array<{ event: string; message: string }> = [];
    // Only the post-publication scan faults; the identity scan before publication reads normally.
    let published = false;
    const scanFault = { ...fs,
      rename: (async (from: string, to: string) => { await fs.rename(from, to); if (path.basename(from) === 'root') published = true; }) as FilesystemPort['rename'],
      readdir: (async (target: string, ...rest: [{ withFileTypes: true }]) => {
        if (published && target.endsWith(`${path.sep}ws${path.sep}ws`)) throw Object.assign(new Error('EIO: scan fault'), { code: 'EIO' });
        return fs.readdir(target, ...rest);
      }) as unknown as FilesystemPort['readdir'] } as FilesystemPort;
    const { result } = await install({ filesystem: scanFault, onEvent: event => events.push(event) }, readerOf(basicEntries()));
    const installed = await result;
    expect((await fs.stat(installed.packageRoot)).isDirectory()).toBe(true);
    expect(events.filter(event => event.event === 'agent-plugin-revision-prune-warning'))
      .toEqual([{ event: 'agent-plugin-revision-prune-warning', message: "Plugin 'edge-plugin': superseded revisions could not be scanned for pruning." }]);
  });
});

