/** Boundary cases of `manifest.ts`'s field validators: each malformed field excludes exactly what it should. */
import { describe, expect, it } from 'vitest';
import { parseAgentPluginManifest, parseAgentPluginMcpConfig, readAgentPluginExtension, type McpServerConfig } from '../../manifest.js';

const PLUGIN_SCHEMA = 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json';
const MCP_SCHEMA = 'https://agent-plugins.org/schemas/1.0.0/mcp.schema.json';
const NAMESPACE = 'org.example.host';

function manifest(fields: Record<string, unknown>) {
  const parsed = parseAgentPluginManifest({ value: { $schema: PLUGIN_SCHEMA, name: 'fixture', ...fields } });
  if (!parsed.ok) throw new Error(parsed.errors.join('; '));
  return parsed.manifest;
}
/** One declared server, with optional namespaced extension metadata for it. */
function server(entry: unknown, extension?: Record<string, unknown>): McpServerConfig | undefined {
  const pluginManifest = { $schema: PLUGIN_SCHEMA, name: 'fixture', extensions: { [NAMESPACE]: { mcpServers: extension ? { one: extension } : {} } } };
  const parsed = parseAgentPluginMcpConfig({ value: { $schema: MCP_SCHEMA, mcpServers: { one: entry } }, extensionNamespace: NAMESPACE }, { pluginManifest });
  if (!parsed.ok) throw new Error(parsed.errors.join('; '));
  return parsed.config.servers.one;
}
const remote = (extension: Record<string, unknown>) => server({ type: 'streamable-http', url: 'https://example.com/mcp' }, extension);
const tokenAuth = (fields: Record<string, unknown>) => remote({ tokenAuth: { helpUrl: 'https://example.com/help', probeUrl: 'https://example.com/probe', ...fields } });

describe('plugin.json author', () => {
  it('keeps a string author', () => {
    expect(manifest({ author: 'Ada' }).author).toBe('Ada');
  });
  it('drops a non-string, non-object author', () => {
    expect(manifest({ author: 42 }).author).toBeUndefined();
  });
  it('keeps only the string members of an object author', () => {
    expect(manifest({ author: { name: 'Ada', email: 5, url: 'https://example.com' } }).author).toEqual({ name: 'Ada', url: 'https://example.com' });
  });
  it('keeps an email-only object author', () => {
    expect(manifest({ author: { email: 'ada@example.com' } }).author).toEqual({ email: 'ada@example.com' });
  });
});

describe('plugin.json shape', () => {
  it('refuses a non-object manifest', () => {
    expect(parseAgentPluginManifest({ value: [] })).toEqual({ ok: false, errors: ['plugin.json must be a JSON object'] });
  });
  // Pinned as found: the identity validator reports the same malformed extensions a second time.
  it('refuses a non-object extensions member', () => {
    const parsed = parseAgentPluginManifest({ value: { $schema: PLUGIN_SCHEMA, name: 'fixture', extensions: [] } });
    expect(parsed).toEqual({ ok: false, errors: ['plugin.json extensions must be an object', 'Plugin extensions must be an object.'] });
  });
  it('accepts a known schema without a version warning', () => {
    const parsed = parseAgentPluginManifest({ value: { $schema: PLUGIN_SCHEMA, name: 'fixture' } });
    expect(parsed.ok && parsed.warnings).toEqual(["Plugin 'fixture' has no publisher-qualified id; using 'unknown/fixture'."]);
  });
  it('omits keywords when the manifest declares none', () => {
    expect(manifest({}).keywords).toBeUndefined();
  });
});

describe('stdio servers', () => {
  it('keeps args, env and cwd when each is well formed', () => {
    expect(server({ type: 'stdio', command: 'node', args: ['a'], env: { MODE: 'x' }, cwd: '/w' }))
      .toEqual({ type: 'stdio', command: 'node', args: ['a'], env: { MODE: 'x' }, cwd: '/w' });
  });
  it('omits absent optional fields', () => {
    expect(server({ type: 'stdio', command: 'node' })).toEqual({ type: 'stdio', command: 'node' });
  });
  it('excludes an empty command', () => {
    expect(server({ type: 'stdio', command: '' })).toBeUndefined();
  });
  it('excludes non-array args', () => {
    expect(server({ type: 'stdio', command: 'node', args: 'a' })).toBeUndefined();
  });
  it('excludes args holding a non-string', () => {
    expect(server({ type: 'stdio', command: 'node', args: ['a', 1] })).toBeUndefined();
  });
  it('excludes an env with a non-string value', () => {
    expect(server({ type: 'stdio', command: 'node', env: { MODE: 1 } })).toBeUndefined();
  });
  it('excludes an env setting a reserved key', () => {
    expect(server({ type: 'stdio', command: 'node', env: { PLUGIN_ROOT: '/x' } })).toBeUndefined();
  });
  it('excludes a non-string cwd', () => {
    expect(server({ type: 'stdio', command: 'node', cwd: 1 })).toBeUndefined();
  });
});

describe('remote servers', () => {
  it('excludes an empty url', () => {
    expect(server({ type: 'sse', url: '' })).toBeUndefined();
  });
  it('excludes headers with a non-string value', () => {
    expect(server({ type: 'sse', url: 'https://example.com', headers: { A: 1 } })).toBeUndefined();
  });
  it('keeps string headers', () => {
    expect(server({ type: 'sse', url: 'https://example.com', headers: { A: 'b' } })).toEqual({ type: 'sse', url: 'https://example.com', headers: { A: 'b' } });
  });
  it('keeps authMode none', () => {
    expect(remote({ authMode: 'none' })).toEqual({ type: 'streamable-http', url: 'https://example.com/mcp', authMode: 'none' });
  });
  it('excludes an unknown authMode', () => {
    expect(remote({ authMode: 'basic' })).toBeUndefined();
  });
  it('excludes non-object defaultTools', () => {
    expect(remote({ defaultTools: ['inspect'] })).toBeUndefined();
  });
  it('excludes a default tool list over the 64-entry bound', () => {
    const names = Array.from({ length: 65 }, (_, index) => `tool${index}`);
    expect(remote({ defaultTools: { allow: names } })).toBeUndefined();
  });
  it('excludes a server entry that is not an object while still listing its id', () => {
    const parsed = parseAgentPluginMcpConfig({ value: { $schema: MCP_SCHEMA, mcpServers: { one: 'stdio' } }, extensionNamespace: NAMESPACE });
    expect(parsed).toEqual({ ok: true, config: { serverIds: ['one'], servers: {} } });
  });
});

describe('remote tokenAuth', () => {
  it('keeps importFromEnv and retiredEnv when both are valid env names', () => {
    expect(tokenAuth({ importFromEnv: 'NEW_TOKEN', retiredEnv: ['OLD_TOKEN'] }))
      .toEqual({ type: 'streamable-http', url: 'https://example.com/mcp', tokenAuth: { helpUrl: 'https://example.com/help', probeUrl: 'https://example.com/probe', importFromEnv: 'NEW_TOKEN', retiredEnv: ['OLD_TOKEN'] } });
  });
  it('excludes a non-object tokenAuth', () => {
    expect(remote({ tokenAuth: 'https://example.com' })).toBeUndefined();
  });
  it('excludes a non-https helpUrl', () => {
    expect(tokenAuth({ helpUrl: 'http://example.com/help' })).toBeUndefined();
  });
  it('excludes an unparseable probeUrl', () => {
    expect(tokenAuth({ probeUrl: 'not a url' })).toBeUndefined();
  });
  it('excludes a non-string helpUrl', () => {
    expect(tokenAuth({ helpUrl: 7 })).toBeUndefined();
  });
  it('excludes a helpUrl over 2048 characters', () => {
    expect(tokenAuth({ helpUrl: `https://example.com/${'a'.repeat(2048)}` })).toBeUndefined();
  });
  it('excludes a lower-case importFromEnv', () => {
    expect(tokenAuth({ importFromEnv: 'token' })).toBeUndefined();
  });
  it('excludes retiredEnv holding an invalid name', () => {
    expect(tokenAuth({ retiredEnv: ['OK', 'bad-name'] })).toBeUndefined();
  });
  it('excludes retiredEnv over the 32-entry bound', () => {
    expect(tokenAuth({ retiredEnv: Array.from({ length: 33 }, (_, index) => `OLD_${index}`) })).toBeUndefined();
  });
});

describe('extension namespaces', () => {
  it('parseAgentPluginMcpConfig refuses a blank namespace', () => {
    expect(() => parseAgentPluginMcpConfig({ value: {}, extensionNamespace: ' ' })).toThrow('An extension namespace is required');
  });
  it('readAgentPluginExtension ignores a namespace whose value is not an object', () => {
    expect(readAgentPluginExtension({ manifest: { extensions: { [NAMESPACE]: 'x' } }, namespace: NAMESPACE, read: () => 'read' })).toBeUndefined();
  });
});

src/admin-surfaces/__tests__/admin-surfa.source:
/**
 * @file The one phase-A vertical-slice proof for admin surfaces: a neutral fixture plugin on disk
 * declares a surface in a HOST-NAMED contribution file; the real contribution loader and trusted file
 * reader admit it; the host serves its entry with the strict headers, mounts it, posts init with a
 * bootstrap, and a surface client round-trips one declared action through the host-page gate and the
 * server dispatcher to a host handler, then asks the host page to open one declared https link
 * through the host's opener port (and is refused an undeclared one). Windows are simulated with structured-clone message passing
 * that, like a browser, drops a message whose target origin does not match the receiver.
 */
import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, expect, test } from 'vitest';
import { createPluginContributionLoader } from '../../lifecycle/contribution-loader.js';
import { readTrustedPluginFile } from '../../lifecycle/__tests__/test-support.js';
import {
  adminSurfaceActionResponse, adminSurfaceInitMessage, createAdminSurfaceActionDispatcher, createAdminSurfaceBootstrap,
  createAdminSurfaceMount, defineAdminSurfaceContribution, openAdminSurfaceLink, readAdminSurfaceFile, validateAdminSurfaceMessage,
} from '../index.js';
import { createAdminSurfaceClient, type AdminSurfaceIncomingMessage } from '../surface-client.js';

const HOST_ORIGIN = 'https://admin.example.com';
const FILENAME = 'acme-admin-surfaces.json';
let root: string | undefined;
afterEach(async () => { if (root) await rm(root, { recursive: true, force: true }); root = undefined; });

/** A window that delivers posted messages to its listeners, dropping any whose target origin is not its own. */
function simulatedWindow(ownOrigin: string) {
  const listeners = new Set<(event: AdminSurfaceIncomingMessage) => void>();
  return {
    listen: (handler: (event: AdminSurfaceIncomingMessage) => void) => { listeners.add(handler); return () => { listeners.delete(handler); }; },
    deliver(required: { readonly data: unknown; readonly targetOrigin: string; readonly origin: string; readonly source: unknown }) {
      if (required.targetOrigin !== '*' && required.targetOrigin !== ownOrigin) return;
      for (const listener of listeners) listener({ origin: required.origin, source: required.source, data: structuredClone(required.data) });
    },
  };
}

test('a fixture plugin surface loads, is served strictly, mounts and round-trips one declared action', async () => {
  root = await mkdtemp(path.join(tmpdir(), 'admin-surface-slice-'));
  await mkdir(path.join(root, 'surface'));
  await writeFile(path.join(root, FILENAME), JSON.stringify({
    schemaVersion: 1,
    surfaces: [{
      id: 'connection-settings', title: 'Connection settings', entry: 'surface/index.html', files: ['surface/app.mjs'],
      actions: [{ name: 'save-selection', input: { type: 'object', properties: { resourceId: { type: 'string', maxLength: 128 } }, required: ['resourceId'] },
        result: { type: 'object', properties: { saved: { type: 'boolean' } }, required: ['saved'] } }],
      csp: { 'connect-src': ['https://api.example.com'] },
      linkOrigins: ['https://accounts.example.com'],
    }],
  }));
  await writeFile(path.join(root, 'surface/index.html'), '<!doctype html><script type="module" src="app.mjs"></script>');
  await writeFile(path.join(root, 'surface/app.mjs'), 'export {};');
  const plugin = { pluginId: 'acme-office', packageRoot: root };

  const loader = createPluginContributionLoader({
    findPackages: async () => [{ trusted: plugin }],
    readFile: ({ plugin: trusted, filename }) => readTrustedPluginFile(trusted, filename),
    importModule: async () => 'surfaces never import code',
  });
  const loaded = await loader.loadPluginContributions({ workspaceId: 'w1', definition: defineAdminSurfaceContribution({ filename: FILENAME }) });
  expect(loaded.refusals).toEqual([]);
  const surface = loaded.items[0]!;

  const served = await readAdminSurfaceFile({ surface, path: surface.descriptor.entry, readFile: ({ plugin: trusted, filename }) => readTrustedPluginFile(trusted, filename) });
  expect(served).toMatchObject({ ok: true, body: '<!doctype html><script type="module" src="app.mjs"></script>', headers: { 'Content-Type': 'text/html; charset=utf-8' } });
  expect(served.ok && served.headers['Content-Security-Policy']).toContain('connect-src https://api.example.com; frame-src');

  const handled: unknown[] = [];
  const { dispatch } = createAdminSurfaceActionDispatcher<{ readonly workspaceId: string }>({
    descriptor: surface.descriptor,
    handlers: { 'save-selection': async ({ payload, context }) => { handled.push({ payload, context }); return { saved: true }; } },
  });
  const mount = createAdminSurfaceMount({ surfaceId: surface.descriptor.id });
  const hostWindow = simulatedWindow(HOST_ORIGIN);
  const frameWindow = simulatedWindow('null');
  const frameRecord = { mountId: mount.mountId, frame: frameWindow, descriptor: surface.descriptor };

  // How the frame sees its parent: posting to it lands in the host window as a message from the frame.
  const parentPort = { postMessage: (data: unknown, targetOrigin: string) => hostWindow.deliver({ data, targetOrigin, origin: 'null', source: frameWindow }) };
  const serverRoundTrips: Promise<void>[] = [];
  const opened: string[] = [];
  hostWindow.listen((event) => {
    serverRoundTrips.push(openAdminSurfaceLink({ event, mount: frameRecord, openLink: ({ url }) => { opened.push(url); } }).then((link) => {
      if ('response' in link) frameWindow.deliver({ data: link.response, targetOrigin: '*', origin: HOST_ORIGIN, source: parentPort });
    }));
    const verdict = validateAdminSurfaceMessage({ event, mount: frameRecord });
    if (!verdict.ok) return;
    // The host page forwards to its server route as JSON; the server, not the frame, supplies context.
    const body = JSON.parse(JSON.stringify({ action: verdict.request.action, payload: verdict.request.payload }));
    serverRoundTrips.push(dispatch({ ...body, context: { workspaceId: 'w1' } }).then((outcome) => {
      frameWindow.deliver({ data: adminSurfaceActionResponse({ request: verdict.request, outcome }), targetOrigin: '*', origin: HOST_ORIGIN, source: parentPort });
    }));
  });

  const client = createAdminSurfaceClient({ parent: parentPort, listen: frameWindow.listen }, { nowMs: () => 2_000 });

  const bootstrap = createAdminSurfaceBootstrap({ surfaceId: surface.descriptor.id, data: { mode: 'pick' }, nowMs: 1_000 });
  frameWindow.deliver({ data: adminSurfaceInitMessage({ mountId: mount.mountId }, { bootstrap }), targetOrigin: '*', origin: HOST_ORIGIN, source: parentPort });
  await client.ready;
  expect(client.bootstrap()).toEqual({ mode: 'pick' });

  const result = client.call({ action: 'save-selection', payload: { resourceId: 'res-1' } });
  await Promise.resolve();
  await Promise.all(serverRoundTrips);
  await expect(result).resolves.toEqual({ saved: true });
  expect(handled).toEqual([{ payload: { resourceId: 'res-1' }, context: { workspaceId: 'w1' } }]);

  const link = client.openLink({ url: 'https://accounts.example.com/permissions' });
  await Promise.resolve();
  await Promise.all(serverRoundTrips);
  await expect(link).resolves.toBeUndefined();
  const undeclared = client.openLink({ url: 'https://elsewhere.example.net/' });
  await Promise.resolve();
  await Promise.all(serverRoundTrips);
  await expect(undeclared).rejects.toMatchObject({ name: 'AdminSurfaceCallError', code: 'link-undeclared', retryable: false });
  expect(opened).toEqual(['https://accounts.example.com/permissions']);
  client.close();
});

src/lifecycle/__tests__/unit/activation-.source:
import { afterEach, describe, expect, test } from 'vitest';
import * as fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { ACTIVATIONS_FILENAME, AgentPluginActivationsBusyError, createAgentPluginActivations } from '../../activation.js';
import type { FilesystemPort } from '../../ports.js';
import { ports } from '../test-support.js';
import { forceRemove } from '../fixtures/force-remove.js';

/**
 * @file `createAgentPluginActivations` — the activation-only object API a host binds without the
 * rest of the lifecycle — plus the unreadable-file, platform and best-effort-fsync paths of the
 * shared activation module, driven through injected filesystem/process ports.
 */

const temporaries: string[] = [];
afterEach(async () => { for (const dir of temporaries.splice(0)) await forceRemove(dir); });
async function workspace(): Promise<string> {
  const dir = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'activation-edges-')));
  temporaries.push(dir);
  return dir;
}
const { filesystem, clock, ids, process: hostProcess } = ports;
/** Each call gets a fresh port object, so each gets its own activation module instance. */
function activations(overrides: { filesystem?: FilesystemPort; platform?: NodeJS.Platform } = {}, onEvent?: (event: { message: string }) => void) {
  const required = { filesystem: overrides.filesystem ?? filesystem, clock, ids,
    process: overrides.platform ? { ...hostProcess, platform: overrides.platform } : hostProcess };
  return onEvent ? createAgentPluginActivations(required, { onEvent }) : createAgentPluginActivations(required);
}

describe('createAgentPluginActivations object API', () => {
  test('writes, reads, resolves, filters and deletes decisions for one workspace', async () => {
    const root = await workspace();
    const api = activations({}, () => undefined);
    await api.assertAgentPluginActivationsWritable({ workspaceRoot: root });
    const written = await api.setAgentPluginActivation({ workspaceRoot: root, pluginId: 'off-plugin', enabled: false, actor: 'operator' },
      { now: () => new Date('2026-03-04T05:06:07.000Z') });
    expect(written.plugins['off-plugin']).toEqual({ enabled: false, origin: 'operator-installed', updatedAt: '2026-03-04T05:06:07.000Z', updatedBy: 'operator' });
    const read = await api.readAgentPluginActivations({ workspaceRoot: root });
    expect(api.normalizeActivations({ value: JSON.parse(await fs.readFile(path.join(root, ACTIVATIONS_FILENAME), 'utf8')) })).toEqual(read);
    expect(api.isAgentPluginActive({ activations: read, pluginId: 'off-plugin' })).toBe(false);
    expect(api.filterActiveAgentPlugins({ activations: read, items: ['off-plugin', 'unrecorded'], pluginIdOf: ({ item }) => item })).toEqual(['unrecorded']);
    expect((await api.resolveAgentPluginActivation({ workspaceRoot: root, pluginId: 'off-plugin' })).verdict).toBe('inactive');
    expect(await api.isAgentPluginRecordedAsBundled({ workspaceRoot: root, pluginId: 'off-plugin' })).toBe(false);
    await api.deleteAgentPluginActivation({ workspaceRoot: root, pluginId: 'off-plugin' });
    expect((await api.readAgentPluginActivations({ workspaceRoot: root })).plugins).toEqual({});
  });

  test('bundled seeding records the given time, origin and seed actor', async () => {
    const root = await workspace();
    const api = activations();
    const now = () => new Date('2026-05-06T07:08:09.000Z');
    expect(await api.recordBundledAgentPluginIfAbsent({ workspaceRoot: root, pluginId: 'bundled-one' }, { now, enabled: true })).toMatchObject({ recorded: true });
    const read = await api.readAgentPluginActivations({ workspaceRoot: root });
    expect(read.plugins['bundled-one']).toMatchObject({ enabled: true, origin: 'bundled', updatedAt: '2026-05-06T07:08:09.000Z' });
    expect(await api.isAgentPluginRecordedAsBundled({ workspaceRoot: root, pluginId: 'bundled-one' })).toBe(true);
  });
});

describe('unreadable activation files', () => {
  test('a read fault other than ENOENT makes the decision undetermined, naming the fault', async () => {
    const root = await workspace();
    await fs.mkdir(path.join(root, ACTIVATIONS_FILENAME));
    const verdict = await activations().resolveAgentPluginActivation({ workspaceRoot: root, pluginId: 'any' });
    expect(verdict).toMatchObject({ verdict: 'undetermined' });
    expect((verdict as { reason: string }).reason).toContain(`${ACTIVATIONS_FILENAME} could not be read (`);
    expect((verdict as { reason: string }).reason).toContain('EISDIR');
  });
  test.each([
    ['a thrown string', 'disk on fire', '(disk on fire)'],
    ['an object with a numeric code', { code: 5 }, '([object Object])'],
  ])('%s from the filesystem is still reported as unreadable, not as absent', async (_label, thrown, rendered) => {
    const root = await workspace();
    const failing = { ...filesystem, readFile: (async () => { throw thrown; }) as FilesystemPort['readFile'] } as FilesystemPort;
    const verdict = await activations({ filesystem: failing }).resolveAgentPluginActivation({ workspaceRoot: root, pluginId: 'any' });
    expect(verdict).toEqual({ verdict: 'undetermined', reason: `${ACTIVATIONS_FILENAME} could not be read ${rendered}` });
  });
});

describe('durable write platform handling', () => {
  test('win32 skips the directory fsync, which cannot open a directory there', async () => {
    const root = await workspace();
    const opened: string[] = [];
    const tracking = { ...filesystem, open: (async (target: string, ...rest: [string?, number?]) => {
      opened.push(target);
      return filesystem.open(target, ...rest);
    }) as FilesystemPort['open'] } as FilesystemPort;
    await activations({ filesystem: tracking, platform: 'win32' }).setAgentPluginActivation({ workspaceRoot: root, pluginId: 'p', enabled: true, actor: 'operator' });
    expect(opened).not.toContain(root);
    expect((await activations().readAgentPluginActivations({ workspaceRoot: root })).plugins['p']).toMatchObject({ enabled: true });
  });
  test('a directory fsync failure is swallowed because the rename already landed', async () => {
    const root = await workspace();
    const failingDirOpen = { ...filesystem, open: (async (target: string, ...rest: [string?, number?]) => {
      if (target === root) throw Object.assign(new Error('EPERM: no directory handles'), { code: 'EPERM' });
      return filesystem.open(target, ...rest);
    }) as FilesystemPort['open'] } as FilesystemPort;
    const written = await activations({ filesystem: failingDirOpen, platform: 'linux' }).setAgentPluginActivation({ workspaceRoot: root, pluginId: 'p', enabled: false, actor: 'operator' });
    expect(written.plugins['p']).toMatchObject({ enabled: false });
    expect((await activations().readAgentPluginActivations({ workspaceRoot: root })).plugins['p']).toMatchObject({ enabled: false });
  });
});

test('a busy-lock error without a readable holder says the holder is unknown and that nothing was written', () => {
  const error = new AgentPluginActivationsBusyError({ lockPath: '/ws/activations.json.lock', holder: undefined, lost: false });
  expect(error.message).toContain('could not take the write lock (/ws/activations.json.lock) within 15s — holder unknown.');
  expect(error.message).toContain('Nothing was written');
  expect(error).toMatchObject({ lockPath: '/ws/activations.json.lock', holder: undefined, lost: false });
});

src/lifecycle/__tests__/unit/trusted-plu.source:
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "../legacy-test.js";

import { setAgentPluginActivation } from "../test-support.js";

import { recordBundledAgentPluginDigests } from "../test-support.js";

import { installAgentPlugin } from "../test-support.js";
import { type AgentPluginArchiveEntry } from "../../install.js";
import { importContainedModule, readTrustedPluginFile } from "../test-support.js";
const MAIL_ADAPTERS_FILENAME = "fixture-adapters.json";
import { resolveAgentPluginLayout } from "../test-support.js";

import { findTrustedPluginPackages } from "../test-support.js";
import { type TrustedPluginPackage } from "../../trusted-plugin-files.js";
import { forceRemove } from "../fixtures/force-remove.js";

/**
 * @file `trusted-plugin-files.ts` — the options the mail-adapter and source-control seams need from
 * the shared gate: plugin-id order, and hearing a switched-off plugin without trusting it. The gates
 * themselves are covered through each seam's own registry suite. Every case installs a REAL package.
 */

const WORKSPACE_ID = "workspace-local";
const SEAM_FILE = "host-fixture-seam.json";

function fileEntry(entryPath: string, content: string): AgentPluginArchiveEntry {
  const bytes = Buffer.from(content, "utf8");
  return {
    kind: "file",
    entryPath,
    declaredSize: bytes.byteLength,
    executable: false,
    async *openReadStream() {
      yield bytes;
    },
  };
}

async function installBundled(workspaceRoot: string, pluginId: string, enabled = true, files: Readonly<Record<string, string>> = {}): Promise<void> {
  const entries = [
    fileEntry("plugin.json", JSON.stringify({ $schema: "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json", name: pluginId, version: "1.0.0" })),
    fileEntry(SEAM_FILE, "{}"),
    ...Object.entries(files).map(([name, body]) => fileEntry(name, body)),
  ];
  const archive = new Uint8Array(Buffer.from(`${pluginId}:seam`));
  const installed = await installAgentPlugin({
    archive,
    expectedSha256: createHash("sha256").update(archive).digest("hex"),
    archiveReader: {
      async *entries() {
        yield* entries;
      },
    },
    layout: resolveAgentPluginLayout(),
    workspaceId: WORKSPACE_ID,
  });
  await recordBundledAgentPluginDigests({ workspaceRoot, seeded: [{ pluginId, archiveDigest: installed.archiveDigest }] });
  await setAgentPluginActivation({ workspaceRoot, pluginId, enabled, actor: "test" }, { origin: "bundled" });
}

async function withWorkspace<T>(fn: (workspaceRoot: string) => Promise<T>): Promise<T> {
  const dir = await mkdtemp(path.join(tmpdir(), "host-trusted-plugin-files-"));
  const previous = process.env.PLUGIN_ROOT;
  process.env.PLUGIN_ROOT = dir;
  try {
    return await fn(resolveAgentPluginLayout().forWorkspace({ workspaceId: WORKSPACE_ID }).root);
  } finally {
    if (previous === undefined) delete process.env.PLUGIN_ROOT;
    else process.env.PLUGIN_ROOT = previous;
    await forceRemove(dir);
  }
}

function trustedIds(verdicts: Awaited<ReturnType<typeof findTrustedPluginPackages>>): string[] {
  return verdicts.map((verdict) => ("trusted" in verdict ? verdict.trusted.pluginId : verdict.refusal));
}

test("orderByPluginId returns trusted packages sorted by plugin id", async () => {
  await withWorkspace(async (workspaceRoot) => {
    for (const pluginId of ["zeta-seam", "alpha-seam", "mid-seam"]) await installBundled(workspaceRoot, pluginId);

    const verdicts = await findTrustedPluginPackages({ workspaceId: WORKSPACE_ID, filename: SEAM_FILE, contribution: "fixtures", requireActive: true, orderByPluginId: true });

    assert.deepEqual(trustedIds(verdicts), ["alpha-seam", "mid-seam", "zeta-seam"]);
  });
});

test("onInactive hears a switched-off plugin, which is neither trusted nor refused", async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installBundled(workspaceRoot, "on-seam");
    await installBundled(workspaceRoot, "off-seam", false);
    const heard: TrustedPluginPackage[] = [];

    const verdicts = await findTrustedPluginPackages({
      workspaceId: WORKSPACE_ID,
      filename: SEAM_FILE,
      contribution: "fixtures",
      requireActive: true,
      onInactive: async ({ plugin }) => {
        heard.push(plugin);
      },
    });

    assert.deepEqual(trustedIds(verdicts), ["on-seam"]);
    assert.deepEqual(heard.map((plugin) => plugin.pluginId), ["off-seam"]);
    assert.ok(heard[0]!.packageRoot.length > 0);
  });
});

test("without requireActive a switched-off plugin is trusted and onInactive is never called", async () => {
  await withWorkspace(async (workspaceRoot) => {
    await installBundled(workspaceRoot, "off-seam", false);
    let calls = 0;

    const verdicts = await findTrustedPluginPackages({
      workspaceId: WORKSPACE_ID,
      filename: SEAM_FILE,
      contribution: "fixtures",
      requireActive: false,
      onInactive: async () => {
        calls += 1;
      },
    });

    assert.deepEqual(trustedIds(verdicts), ["off-seam"]);
    assert.equal(calls, 0);
  });
});


test("unreadable activation refuses a bundled executable contribution before its module runs", async () => {
  await withWorkspace(async workspaceRoot => {
    const marker = "__trustedPluginAuditExecuted";
    await installBundled(workspaceRoot, "blocked-mail", true, {
      [MAIL_ADAPTERS_FILENAME]: JSON.stringify({ schemaVersion: 1, adapters: [{ id: "blocked-mail", label: "Blocked Mail", module: "adapter.mjs", credentialLabel: "Key" }] }),
      "adapter.mjs": `globalThis[${JSON.stringify(marker)}] = true; export default { create() { return {}; } };`,
    });
    await writeFile(path.join(workspaceRoot, "activations.json"), "{broken-json");
    const verdicts = await findTrustedPluginPackages({ workspaceId: WORKSPACE_ID, filename: MAIL_ADAPTERS_FILENAME, contribution: "mail adapters", requireActive: true });
    assert.equal(verdicts.length, 1);
    assert.ok("refusal" in verdicts[0]!);
    const first = verdicts[0]!;
    if (!("refusal" in first)) throw new Error("expected refusal");
    assert.match(first.refusal, /activation could not be read/);
    const imported: unknown[] = [];
    for (const verdict of verdicts) {
      if ('trusted' in verdict) imported.push(await importContainedModule(verdict.trusted, 'adapter.mjs'));
    }
    assert.deepEqual(imported, []);
    assert.equal((globalThis as Record<string, unknown>)[marker], undefined, "the refused module must never be imported");
  });
});

test('trusted file reads reject traversal outside the package root', async () => {
  await withWorkspace(async workspaceRoot => {
    await installBundled(workspaceRoot, 'contained-seam');
    const verdicts = await findTrustedPluginPackages({ workspaceId: WORKSPACE_ID, filename: SEAM_FILE, contribution: 'fixtures', requireActive: true });
    const first = verdicts[0]!;
    if (!('trusted' in first)) throw new Error('expected trusted fixture');
    await assert.rejects(() => readTrustedPluginFile(first.trusted, '../../../outside.txt'));
    assert.equal(await readTrustedPluginFile(first.trusted, SEAM_FILE), '{}');
  });
});

