/** `createInstalledPackageIndex().indexInstalledRoot()` — reading one installed package's manifest and file tree. */
import { afterEach, describe, expect, it } from 'vitest';
import { mkdir, mkdtemp, realpath, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { AgentPluginInstallError } from '../../install-errors.js';
import { createInstalledPackageIndex } from '../../installed-package-index.js';
import type { AgentPluginLifecyclePorts } from '../../ports.js';
import { forceRemove } from '../fixtures/force-remove.js';
import { ports } from '../test-support.js';

const SCHEMA = 'https://agent-plugins.org/schemas/1.0.0/plugin.schema.json';
const DIGEST = 'a'.repeat(64);
const roots: string[] = [];
afterEach(async () => { for (const root of roots.splice(0)) await forceRemove(root); });

async function packageRoot(files: Record<string, string> = {}): Promise<string> {
  const root = await realpath(await mkdtemp(path.join(tmpdir(), 'jini-package-index-')));
  roots.push(root);
  for (const [relative, content] of Object.entries(files)) {
    await mkdir(path.dirname(path.join(root, relative)), { recursive: true });
    await writeFile(path.join(root, relative), content);
  }
  return root;
}
const manifest = (fields: Record<string, unknown> = {}) => JSON.stringify({ $schema: SCHEMA, name: 'my-plugin', ...fields });
const index = (root: string, host: AgentPluginLifecyclePorts = ports) => createInstalledPackageIndex({ ports: host }).indexInstalledRoot({ packageRoot: root, archiveDigest: DIGEST });

describe('indexInstalledRoot refusals', () => {
  it('reports MANIFEST_MISSING when plugin.json is absent', async () => {
    await expect(index(await packageRoot())).rejects.toMatchObject({ code: 'MANIFEST_MISSING', message: 'the archive does not contain a plugin.json at its root' });
  });

  it('propagates a plugin.json read fault other than a missing file', async () => {
    const root = await packageRoot();
    await mkdir(path.join(root, 'plugin.json'));
    await expect(index(root)).rejects.toMatchObject({ code: 'EISDIR' });
  });

  it('reports MANIFEST_INVALID with the parse error as cause for malformed JSON', async () => {
    const error = await index(await packageRoot({ 'plugin.json': '{' })).catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(AgentPluginInstallError);
    expect(error).toMatchObject({ code: 'MANIFEST_INVALID', message: 'plugin.json is not valid JSON', cause: expect.any(SyntaxError) });
  });

  it('reports MANIFEST_INVALID with the validation errors for a manifest that fails the grammar', async () => {
    await expect(index(await packageRoot({ 'plugin.json': JSON.stringify({ $schema: SCHEMA }) })))
      .rejects.toMatchObject({ code: 'MANIFEST_INVALID', message: "plugin.json failed validation: plugin.json 'name' is required and must be a string" });
  });
});

describe('indexInstalledRoot results', () => {
  it('indexes every regular file sorted and every skill sorted by name', async () => {
    const root = await packageRoot({ 'plugin.json': manifest(), 'skills/zeta/SKILL.md': '#', 'skills/alpha/SKILL.md': '#', 'skills/alpha/notes.md': '' });
    const indexed = await index(root);
    expect(indexed.files).toEqual(['plugin.json', 'skills/alpha/SKILL.md', 'skills/alpha/notes.md', 'skills/zeta/SKILL.md']);
    expect(indexed.skills).toEqual([{ name: 'alpha', skillPath: 'skills/alpha/SKILL.md' }, { name: 'zeta', skillPath: 'skills/zeta/SKILL.md' }]);
  });

  it('skips an entry that is neither a directory nor a regular file', async () => {
    const root = await packageRoot({ 'plugin.json': manifest() });
    await symlink(path.join(root, 'plugin.json'), path.join(root, 'link.json'));
    expect((await index(root)).files).toEqual(['plugin.json']);
  });

  it('omits every optional manifest field the manifest does not declare', async () => {
    expect(await index(await packageRoot({ 'plugin.json': manifest() }))).toEqual({
      pluginId: 'my-plugin', id: 'unknown/my-plugin', provides: [], version: undefined,
      archiveDigest: DIGEST, packageRoot: expect.any(String), files: ['plugin.json'], skills: [],
    });
  });

  it('carries description, keywords, author and license through', async () => {
    const indexed = await index(await packageRoot({ 'plugin.json': manifest({ description: 'd', keywords: ['k'], author: 'a', license: 'MIT' }) }));
    expect(indexed).toMatchObject({ description: 'd', keywords: ['k'], author: 'a', license: 'MIT' });
  });

  it('carries validated exports and declared old identities without reading templates', async () => {
    const definition = { template: 'exports/button.html', props: { type: 'object' }, consent: 'necessary', staticExport: 'fallback-only', version: 1 };
    const metadata = { exports: { button: definition }, renamedFrom: ['publisher/previous'] };
    const root = await packageRoot({ 'plugin.json': manifest({ extensions: { [ports.extensionNamespace]: metadata } }) });
    const indexed = await index(root);
    expect(indexed.exports).toEqual(metadata.exports);
    expect(indexed.renamedFrom).toEqual(metadata.renamedFrom);
    expect(indexed.files).toEqual(['plugin.json']);
  });

  it('refuses malformed export metadata at the shared manifest boundary', async () => {
    const root = await packageRoot({ 'plugin.json': manifest({ extensions: { [ports.extensionNamespace]: { exports: { button: {} } } } }) });
    await expect(index(root)).rejects.toMatchObject({ code: 'MANIFEST_INVALID', message: 'plugin.json failed validation: exports.button: version must be a positive safe integer' });
  });

  it('trims and caps the host displayName and summary', async () => {
    const extensions = { [ports.extensionNamespace]: { displayName: `  ${'n'.repeat(70)}  `, summary: ` ${'s'.repeat(1300)} ` } };
    const indexed = await index(await packageRoot({ 'plugin.json': manifest({ extensions }) }));
    expect([indexed.displayName, indexed.summary]).toEqual(['n'.repeat(64), 's'.repeat(1200)]);
  });

  it('ignores a non-string or blank displayName and summary', async () => {
    const extensions = { [ports.extensionNamespace]: { displayName: 7, summary: '   ' } };
    const indexed = await index(await packageRoot({ 'plugin.json': manifest({ extensions }) }));
    expect(['displayName' in indexed, 'summary' in indexed]).toEqual([false, false]);
  });

  it('reports each manifest identity warning as an event', async () => {
    const events: string[] = [];
    await index(await packageRoot({ 'plugin.json': manifest() }), { ...ports, onEvent: ({ message }) => events.push(message) });
    expect(events).toEqual(["Plugin 'my-plugin' has no publisher-qualified id; using 'unknown/my-plugin'."]);
  });
});

src/lifecycle/__tests__/unit/bundled-sou.source:
import assert from "node:assert/strict";
import { packAgentPluginDirectory } from "../test-support.js";
import { mkdir, mkdtemp, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "../legacy-test.js";

import { createBundledSourceArchiveReader } from "../test-support.js";


/**
 * @file The directory-to-archive round trip that lets a bundled package go THROUGH
 * `installAgentPlugin` rather than around it.
 *
 * The two properties that matter: the round trip is lossless (or the installer would publish
 * different bytes than the repo holds), and the digest is deterministic (or seeding would
 * re-extract on every boot instead of hitting the content-addressed dedup path).
 */

async function fixtureDir(files: Readonly<Record<string, string>>): Promise<string> {
  const dir = await mkdtemp(path.join(tmpdir(), "host-bundled-archive-"));
  for (const [relative, content] of Object.entries(files)) {
    const absolute = path.join(dir, relative);
    await mkdir(path.dirname(absolute), { recursive: true });
    await writeFile(absolute, content, "utf8");
  }
  return dir;
}

async function readBack(bytes: Uint8Array): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for await (const entry of createBundledSourceArchiveReader().entries({ archive: bytes })) {
    assert.equal(entry.kind, "file");
    if (entry.kind !== "file") continue;
    const chunks: Uint8Array[] = [];
    for await (const chunk of entry.openReadStream({})) chunks.push(chunk);
    out[entry.entryPath] = Buffer.concat(chunks.map((chunk) => Buffer.from(chunk))).toString("utf8");
  }
  return out;
}

test("packs and unpacks every file losslessly, including nested and non-ASCII content", async () => {
  const files = {
    "plugin.json": '{"name":"x"}',
    "skills/x/SKILL.md": "# X\n\nBody — with an em dash and an emoji 🧭\n",
    "skills/x/references/deep/nested.md": "nested\n",
    "empty.txt": "",
  };
  const dir = await fixtureDir(files);
  try {
    const packed = await packAgentPluginDirectory(dir);
    assert.deepEqual(await readBack(packed.bytes), files);
    assert.deepEqual([...packed.files], Object.keys(files).sort());
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("packed plugins omit tests and their fixtures while preserving runtime files and digest", async () => {
  const runtimeFiles = {
    "plugin.json": '{"name":"runtime-only"}',
    "mcp/server.mjs": "export const ready = true;",
    "skills/runtime/SKILL.md": "# Runtime skill",
    // Runtime examples remain installable even when their names include 'fixture' or 'test'.
    "skills/runtime/examples/fixture.json": '{"example":true}',
    "mcp/test-client.mjs": "export const client = {};",
    "mcp/spec.json": '{"version":1}',
  };
  const dir = await fixtureDir({
    ...runtimeFiles,
    "__tests__/plain.mjs": "test helper",
    "__tests__/fixtures/response.json": "test-only fixture",
    "mcp/__tests__/fixtures.mjs": "nested test-only fixture",
    "mcp/server.test.mjs": "test",
    "mcp/server.spec.mjs": "spec",
    "mcp/server.test.ts": "TypeScript test",
    "mcp/server.spec.js.map": "test source map",
  });
  try {
    const packed = await packAgentPluginDirectory(dir);
    assert.deepEqual([...packed.files], Object.keys(runtimeFiles).sort());
    // Check the encoded archive too: filtering only the reported file list cannot pass.
    assert.deepEqual(await readBack(packed.bytes), runtimeFiles);
    await writeFile(path.join(dir, "__tests__/plain.mjs"), "changed test helper");
    await writeFile(path.join(dir, "mcp/server.test.mjs"), "changed test");
    await writeFile(path.join(dir, "mcp/server.spec.js.map"), "changed test source map");
    const repacked = await packAgentPluginDirectory(dir);
    assert.deepEqual(repacked.bytes, packed.bytes);
    assert.equal(repacked.sha256, packed.sha256,
      "test-only edits must not republish installed runtime packages");
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("the digest is a real SHA-256 of the archive bytes and is deterministic across packs", async () => {
  const dir = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "a" });
  try {
    const first = await packAgentPluginDirectory(dir);
    const second = await packAgentPluginDirectory(dir);
    assert.match(first.sha256, /^[a-f0-9]{64}$/);
    assert.equal(first.sha256, second.sha256, "seeding relies on this to hit the content-addressed dedup path");

    const { createHash } = await import("node:crypto");
    assert.equal(createHash("sha256").update(Buffer.from(first.bytes)).digest("hex"), first.sha256);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("changing one byte of content changes the digest", async () => {
  const before = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "a" });
  const after = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "b" });
  try {
    assert.notEqual((await packAgentPluginDirectory(before)).sha256, (await packAgentPluginDirectory(after)).sha256);
  } finally {
    await rm(before, { recursive: true, force: true });
    await rm(after, { recursive: true, force: true });
  }
});

test("a symlink is skipped rather than followed — the installer would reject one anyway", async () => {
  const dir = await fixtureDir({ "plugin.json": '{"name":"x"}' });
  try {
    await symlink("/etc/passwd", path.join(dir, "sneaky"));
    const packed = await packAgentPluginDirectory(dir);
    assert.deepEqual([...packed.files], ["plugin.json"]);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

test("the reader refuses bytes that are not this format", async () => {
  const reader = createBundledSourceArchiveReader();
  await assert.rejects(async () => {
    for await (const _entry of reader.entries({ archive: new TextEncoder().encode("PK a real zip") })) void _entry;
  }, /bad magic/);
});

test("the reader refuses a truncated archive rather than yielding a partial file", async () => {
  const dir = await fixtureDir({ "plugin.json": '{"name":"x"}', "a.md": "a long enough body to truncate" });
  try {
    const packed = await packAgentPluginDirectory(dir);
    const truncated = packed.bytes.slice(0, packed.bytes.byteLength - 10);
    await assert.rejects(async () => {
      for await (const _entry of createBundledSourceArchiveReader().entries({ archive: truncated })) void _entry;
    }, /truncated entry body/);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

src/__tests__/folder-zip.test.ts.source:
import assert from "node:assert/strict";
import { test } from "vitest";
import { crc32, FOLDER_MAX_FILES, FolderZipError, zipFolderFiles } from "../folder-zip.js";

function picked(required: { name: string; relative?: string; bytes?: Uint8Array }, _optional: Record<string, never> = {}): File {
  const file = new File([new Uint8Array(required.bytes ?? [])], required.name);
  if (required.relative !== undefined) Object.defineProperty(file, "webkitRelativePath", { value: required.relative });
  return file;
}

async function archive(required: { files: File[]; maxBytes?: number }, _optional: Record<string, never> = {}) {
  const file = await zipFolderFiles({ files: required.files, maxBytes: required.maxBytes ?? 10000 });
  const bytes = new Uint8Array(await file.arrayBuffer());
  return { file, bytes, view: new DataView(bytes.buffer) };
}

test("CRC-32 matches the standard check vector and empty input", () => {
  assert.equal(crc32(new TextEncoder().encode("123456789")), 0xcbf43926);
  assert.equal(crc32(new Uint8Array()), 0);
});

test("an empty selection returns the empty-folder refusal", async () => {
  await assert.rejects(() => zipFolderFiles({ files: [], maxBytes: 0 }), new FolderZipError("empty", "That folder is empty."));
});

test("file count is refused before reading or checking raw size", async () => {
  const file = picked({ name: "a" });
  file.arrayBuffer = async () => { throw new Error("must not read"); };
  await assert.rejects(() => zipFolderFiles({ files: Array(FOLDER_MAX_FILES + 1).fill(file), maxBytes: -1 }), {
    reason: "too-many", message: "More than 4096 files.",
  });
});

test("raw size is refused before attempting a file read", async () => {
  const file = picked({ name: "a", bytes: new Uint8Array([1, 2]) });
  file.arrayBuffer = async () => { throw new Error("must not read"); };
  await assert.rejects(() => zipFolderFiles({ files: [file], maxBytes: 1 }), {
    reason: "too-large", message: "Folder is over the upload limit.",
  });
});

test("a failed file read is translated to the unreadable-folder refusal", async () => {
  const file = picked({ name: "a" });
  file.arrayBuffer = async () => { throw new Error("read failed"); };
  await assert.rejects(() => zipFolderFiles({ files: [file], maxBytes: 1000 }), {
    reason: "unreadable", message: "Could not read that folder. Try again.",
  });
});

test("ZIP overhead is included in the limit and equality is accepted", async () => {
  const file = picked({ name: "a" });
  await assert.rejects(() => zipFolderFiles({ files: [file], maxBytes: 99 }), { reason: "too-large" });
  const result = await archive({ files: [file], maxBytes: 100 });
  assert.equal(result.bytes.length, 100);
  assert.equal(result.file.name, "folder.zip");
  assert.equal(result.file.type, "application/zip");
});

test("stored ZIP headers preserve binary bytes, CRC, fixed dates and DOS file attributes", async () => {
  const data = new Uint8Array([0x89, 0, 0xff, 0x80]);
  const { bytes, view } = await archive({ files: [picked({ name: "a", relative: "picked/a", bytes: data })] });
  const central = 35;
  assert.equal(view.getUint32(0, true), 0x04034b50);
  assert.equal(view.getUint16(4, true), 20);
  assert.equal(view.getUint16(6, true), 0);
  assert.equal(view.getUint16(8, true), 0);
  assert.equal(view.getUint16(10, true), 0);
  assert.equal(view.getUint16(12, true), 33);
  assert.equal(view.getUint32(14, true), crc32(data));
  assert.equal(view.getUint32(18, true), 4);
  assert.equal(view.getUint32(22, true), 4);
  assert.deepEqual(bytes.subarray(31, 35), data);
  assert.equal(view.getUint32(central, true), 0x02014b50);
  assert.equal(view.getUint16(central + 4, true), 20);
  assert.equal(view.getUint16(central + 6, true), 20);
  assert.equal(view.getUint16(central + 8, true), 0);
  assert.equal(view.getUint16(central + 14, true), 33);
  assert.equal(view.getUint32(central + 16, true), crc32(data));
  assert.equal(view.getUint32(central + 20, true), 4);
  assert.equal(view.getUint32(central + 24, true), 4);
  assert.equal(view.getUint32(central + 38, true), 0);
  assert.equal(view.getUint32(central + 42, true), 0);
  const end = central + 47;
  assert.equal(view.getUint32(end, true), 0x06054b50);
  assert.equal(view.getUint16(end + 8, true), 1);
  assert.equal(view.getUint16(end + 10, true), 1);
  assert.equal(view.getUint32(end + 12, true), 47);
  assert.equal(view.getUint32(end + 16, true), central);
});

test("non-ASCII paths set UTF-8 flags in both headers and normalize backslashes", async () => {
  const { file, bytes, view } = await archive({ files: [picked({ name: "é", relative: "picked\\nested\\é" })] });
  const name = new TextEncoder().encode("nested/é");
  assert.equal(file.name, "picked.zip");
  assert.equal(view.getUint16(6, true), 0x0800);
  assert.equal(view.getUint16(26, true), name.length);
  assert.deepEqual(bytes.subarray(30, 30 + name.length), name);
  const central = 30 + name.length;
  assert.equal(view.getUint16(central + 8, true), 0x0800);
  assert.equal(view.getUint16(central + 28, true), name.length);
  assert.deepEqual(bytes.subarray(central + 46, central + 46 + name.length), name);
});

test("input order is preserved and the first nonempty folder names the archive", async () => {
  const { file, bytes, view } = await archive({ files: [
    picked({ name: "z" }), picked({ name: "a", relative: "first/a" }), picked({ name: "b", relative: "second/b" }),
  ] });
  assert.equal(file.name, "first.zip");
  assert.equal(new TextDecoder().decode(bytes.subarray(30, 31)), "z");
  assert.equal(new TextDecoder().decode(bytes.subarray(61, 62)), "a");
  assert.equal(new TextDecoder().decode(bytes.subarray(92, 93)), "b");
  const central = 93;
  assert.equal(view.getUint32(central + 42, true), 0);
  assert.equal(view.getUint32(central + 47 + 42, true), 31);
  assert.equal(view.getUint32(central + 94 + 42, true), 62);
});

test("relative paths without a slash stay intact and an empty folder uses the fallback name", async () => {
  const { file, bytes } = await archive({ files: [picked({ name: "ignored", relative: "standalone" })] });
  assert.equal(file.name, "folder.zip");
  assert.equal(new TextDecoder().decode(bytes.subarray(30, 40)), "standalone");
});

test("the exact entry cap is accepted", async () => {
  const { view, bytes } = await archive({ files: Array(FOLDER_MAX_FILES).fill(picked({ name: "a" })), maxBytes: 1000000 });
  assert.equal(view.getUint16(bytes.length - 14, true), FOLDER_MAX_FILES);
});

